import React,{useRef,useState} from 'react';
import {Button,View,Image} from 'react-native';
import {CameraView,useCameraPermissions} from 'expo-camera';
export default function Cam(){
  const[p,req]=useCameraPermissions();const ref=useRef<CameraView>(null);const[u,setU]=useState<string|null>(null);
  if(!p)return null;
  if(!p.granted)return(<View><Button title='allow' onPress={req}/></View>);
  const shoot=async()=>{const r=await ref.current?.takePictureAsync();if(r)setU(r.uri);};
  return(<View style={{flex:1}}>{u?<Image source={{uri:u}} style={{flex:1}}/>:<CameraView ref={ref} style={{flex:1}}/>}<Button title='shoot' onPress={shoot}/></View>);}
